SELECT 'gongkao', '名言警句类', 'kp-ms-ana-quote', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "综合分析：名言警句类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "解释名言的本义，并把它跟公务员的实际工作死死绑定！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、答题框架"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【破题】：用大白话把名言的意思翻译一遍。点出它的核心精神（如：坚持不懈、群众路线、廉洁奉公）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【说理/举例】：结合时代背景，或者举一个感动中国的时代楷模（如黄文秀、张桂梅）的例子，来印证这句话的伟大。这是撑起时长的关键！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【结合自身】：作为一名未来的公职人员，在以后的工作中，我会怎么去践行这句话（表决心）。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "纯谈人生哲学：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "通篇只讲大道理，忘了你是来考公务员的。最后一段如果不落脚到“基层工作、为人民服务”，直接沦为二类答卷。"}]}]}]}$$ AS jsonb), NULL, '名言警句类的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "综合分析", "名言警句"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_ana_quote", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
